/// `bank`: every failure reply on `game_response`, in check order.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum BankFailure {
    BankFailureBankUnavailable(Box<BankFailureBankUnavailable>),
    BankFailureInvalid(Box<BankFailureInvalid>),
    BankFailureGoldNotEnough(Box<BankFailureGoldNotEnough>),
    BankFailureBankOpi(Box<BankFailureBankOpi>),
    BankFailureBankNewPackFailed(Box<BankFailureBankNewPackFailed>),
    BankFailureItemPlaceholder(Box<BankFailureItemPlaceholder>),
    BankFailureItemBlocked(Box<BankFailureItemBlocked>),
    BankFailureStorageFull(Box<BankFailureStorageFull>),
    BankFailureInventoryFull(Box<BankFailureInventoryFull>),
}

/// `bet`, variant dice: The dice table: bet that the roll (0 to 99.99) lands above or below
