/// `bet` reply (With request_id): A restart starts (`tavern_close`) before your wager settled.
/// One reply per wager: an open dice bet, a wheel spin or a slots pull. Without `request_id`
/// you get only the `game_log` of the refund. An open roulette bet is in `player.bets` too, so
/// the dice refund returns it, with `place: "dice"`; it never has `request_id`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BetRefund {
    #[serde(rename = "response")]
    pub response: LitTavernClosing,
    #[serde(rename = "place")]
    pub place: LitDiceSlotsWheel,
    #[serde(rename = "failed")]
    pub failed: bool,
    #[serde(rename = "request_id")]
    pub request_id: Value,
    #[serde(rename = "reason")]
    pub reason: LitTavernClosing,
    #[serde(rename = "refund")]
    pub refund: i64,
    /// The keys this struct does not name.
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

/// `bet` reply: All checks pass. Two `game_log` events: this one (`server.game_log.num`), then
/// `server.game_log.bet_gold` with `{amount}` ("Bet: 100,000 gold", color `"gray"`). There is
/// no `game_response` now.
pub type BetDiceAccepted = LocalizedText;

/// `bet` reply: At the end of the round, when the roll is on your side of `num`. Two `game_log`
/// events: this one with the gross win, then `server.game_log.house_edge_gold` with `{amount:
/// edge}` ("House edge: 2,000 gold", color `"gray"`).
pub type BetDiceWon = LocalizedText;

/// `bet` reply: At the end of the round, when the roll is not on your side.
pub type BetDiceLost = LocalizedText;

/// `bet` reply (With request_id): At the end of the round, after the `game_log`. It has no
/// `failed` field for a loss: `success` is `true` and `won` is `false`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BetDiceResult {
    #[serde(rename = "response")]
    pub response: LitData,
    #[serde(rename = "place")]
    pub place: LitDice,
    #[serde(rename = "success")]
    pub success: bool,
    #[serde(rename = "request_id")]
    pub request_id: Value,
    #[serde(rename = "won")]
    pub won: bool,
    #[serde(rename = "roll")]
    pub roll: f64,
    #[serde(rename = "num")]
    pub num: f64,
    #[serde(rename = "direction")]
    pub direction: LitDownUp,
    #[serde(rename = "wager")]
    pub wager: i64,
    #[serde(rename = "payout")]
    pub payout: i64,
    #[serde(rename = "net")]
    pub net: i64,
    #[serde(rename = "edge")]
    pub edge: i64,
    /// The keys this struct does not name.
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

/// `bet` reply: All checks pass. The server picks the slice now (`crypto.randomInt` over the 14
/// slices of `G.games.wheel.slices`, 7 per side) and takes the stake. `phrase_args.side` is an
/// object: the phrase of the side.
pub type BetWheelAccepted = LocalizedText;

/// `bet` reply: 4,000 ms later (`player.q.wheel`). `server.game_log.wheel_won` with the net
/// win, or `server.game_log.wheel_lost` with the stake. `side` is the side of the slice.
pub type BetWheelStopped = LocalizedText;

