pub struct ConvertShells {
    #[serde(rename = "message")]
    pub message: String,
    #[serde(rename = "phrase")]
    pub phrase: LitServerShellsReceived,
    #[serde(rename = "phrase_args")]
    pub phrase_args: Map<String, Value>,
    #[serde(rename = "color")]
    pub color: LitGreen,
    /// The keys this struct does not name.
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

/// `convert` reply: After the shells: the slot is empty. A second `player` with `reopen: true`
/// follows when the account update is saved.
pub type ConvertUpdated = PlayerEvent;

